SELECT CURRENCY
  FROM SYX2MM
 WHERE CORP_GR = #{corpGr}
   AND TRUSTEE = #{trustee}
 FETCH FIRST 1 ROWS ONLY

SELECT GIJUN_RT
  FROM SYX1HY
 WHERE CORP_GR   = #{corpGr}
   AND GIJUN_YMD = TO_DATE(REPLACE(#{gijunYmd}, '-', ''), 'YYYYMMDD')
   AND CURRENCY  = #{currency}
 FETCH FIRST 1 ROWS ONLY

mapper.update:
UPDATE SYT0MA
   SET FUND_CD      = #{fundCd, jdbcType=VARCHAR}
     , TRUSTEE      = #{trustee, jdbcType=VARCHAR}
     , CURRENCY     = #{currency, jdbcType=VARCHAR}
     , TR_SEQ       = COALESCE(#{trSeq, jdbcType=NUMERIC}, TR_SEQ)
     , GYULJE_YMD   = TO_DATE(REPLACE(#{gyuljeYmd, jdbcType=VARCHAR}, '-', ''), 'YYYYMMDD')
     , TR_AEK       = COALESCE(#{trAek, jdbcType=NUMERIC}, 0)
     , WON_TR_AEK   = COALESCE(#{wonTrAek, jdbcType=NUMERIC}, 0)
     , BAL_AEK      = COALESCE(#{balAek, jdbcType=NUMERIC}, 0)
     , WON_BAL_AEK  = COALESCE(#{wonBalAek, jdbcType=NUMERIC}, 0)
     , TAX_AEK      = COALESCE(#{taxAek, jdbcType=NUMERIC}, 0)
     , WON_TAX_AEK  = COALESCE(#{wonTaxAek, jdbcType=NUMERIC}, 0)
     , FCUR_TR_AEK  = #{syt0maFcurTrAek, jdbcType=NUMERIC}
     , FCUR_BAL_AEK = #{syt0maFcurBalAek, jdbcType=NUMERIC}
 WHERE CORP_GR    = #{corpGr, jdbcType=VARCHAR}
   AND TR_YMD     = TO_DATE(REPLACE(#{trYmd, jdbcType=VARCHAR}, '-', ''), 'YYYYMMDD')
   AND TR_CD      = #{trCd, jdbcType=VARCHAR}
   AND FUND_CD    = COALESCE(#{origFundCd, jdbcType=VARCHAR}, #{fundCd, jdbcType=VARCHAR})
   AND TRUSTEE    = COALESCE(#{origTrustee, jdbcType=VARCHAR}, #{trustee, jdbcType=VARCHAR})
   AND CURRENCY   = COALESCE(#{origCurrency, jdbcType=VARCHAR}, #{currency, jdbcType=VARCHAR})
   AND TR_SEQ     = COALESCE(#{origTrSeq, jdbcType=NUMERIC}, #{trSeq, jdbcType=NUMERIC})
   AND GYULJE_YMD = TO_DATE(REPLACE(COALESCE(#{origGyuljeYmd, jdbcType=VARCHAR}, #{gyuljeYmd, jdbcType=VARCHAR}), '-', ''), 'YYYYMMDD')
